def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end without closing quote
                return None

            # Check what follows the closing quote
            if i < n and line[i] != ',':
                return None

            fields.append(''.join(field))

            # Skip the comma if present
            if i < n:
                i += 1
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            # Skip the comma if present
            if i < n:
                i += 1

    return fields

